import{_ as t,o as n,c as o,a2 as a}from"./chunks/framework.D7WGirly.js";const d=JSON.parse('{"title":"Integrations — How-tos & Workflows","description":"","frontmatter":{},"headers":[],"relativePath":"integrations-02-how-tos-and-workflows.md","filePath":"integrations-02-how-tos-and-workflows.md"}'),i={name:"integrations-02-how-tos-and-workflows.md"};function s(r,e,l,c,g,u){return n(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="integrations-—-how-tos-workflows" tabindex="-1">Integrations — How-tos &amp; Workflows <a class="header-anchor" href="#integrations-—-how-tos-workflows" aria-label="Permalink to &quot;Integrations — How-tos &amp; Workflows&quot;">​</a></h1><p><em>Step-by-step guides for connecting and configuring Fireflies, Gong, JIRA, and Asana</em></p><hr><h2 id="connecting-fireflies" tabindex="-1">Connecting Fireflies <a class="header-anchor" href="#connecting-fireflies" aria-label="Permalink to &quot;Connecting Fireflies&quot;">​</a></h2><p>The Fireflies integration allows meeting transcripts to be imported directly into the Extracts module, without manual file upload.</p><ol><li>Go to Settings &gt; Integrations.</li><li>Find the Fireflies integration and select Connect.</li><li>Authenticate with your Fireflies account.</li><li>Once connected, the Fireflies import option becomes available in the Extracts module.</li></ol><p>Once connected, any meeting in your Fireflies instance is available for import into Extracts. See the Extracts module guide for how to use this in practice.</p><h3 id="configuring-fireflies-auto-sync" tabindex="-1">Configuring Fireflies auto-sync <a class="header-anchor" href="#configuring-fireflies-auto-sync" aria-label="Permalink to &quot;Configuring Fireflies auto-sync&quot;">​</a></h3><p>After connecting, you can configure Lodestone to pull new Fireflies transcripts automatically:</p><ol><li>In the Fireflies integration settings, enable <strong>Automatic Sync</strong>.</li><li>Choose a <strong>Sync Interval</strong>: every 12 hours, 24 hours, or weekly.</li><li>Set a <strong>Lookback Window</strong> — how many days back Lodestone should look for new transcripts on each sync cycle (1–90 days).</li><li>Save. Lodestone will now pull new transcripts from Fireflies on your chosen schedule and queue them for analysis in Extracts automatically.</li></ol><blockquote><p><strong>Tip:</strong> A 24-hour interval with a 7-day lookback is a good default for most teams — you get daily updates without capturing stale meetings.</p></blockquote><hr><h2 id="connecting-fathom" tabindex="-1">Connecting Fathom <a class="header-anchor" href="#connecting-fathom" aria-label="Permalink to &quot;Connecting Fathom&quot;">​</a></h2><p>The Fathom integration imports meeting transcripts and AI-generated meeting notes directly into the Extracts module.</p><ol><li>Go to Settings &gt; Integrations.</li><li>Find the Fathom integration and select Connect.</li><li>Enter your Fathom API key. You can generate an API key from your Fathom account settings.</li><li>Lodestone verifies the connection. Once confirmed, it is saved automatically.</li></ol><h3 id="configuring-fathom-auto-sync" tabindex="-1">Configuring Fathom auto-sync <a class="header-anchor" href="#configuring-fathom-auto-sync" aria-label="Permalink to &quot;Configuring Fathom auto-sync&quot;">​</a></h3><p>After connecting, you can configure Lodestone to pull new Fathom transcripts automatically:</p><ol><li>In the Fathom integration settings, enable <strong>Automatic Sync</strong>.</li><li>Choose a <strong>Sync Interval</strong>: every 12 hours, 24 hours, or weekly.</li><li>Set a <strong>Lookback Window</strong> — how many days back Lodestone should look for new transcripts on each sync cycle (1–90 days).</li><li>Save. Lodestone will now pull new Fathom transcripts on your chosen schedule and queue them for analysis in Extracts automatically.</li></ol><hr><h2 id="connecting-granola" tabindex="-1">Connecting Granola <a class="header-anchor" href="#connecting-granola" aria-label="Permalink to &quot;Connecting Granola&quot;">​</a></h2><p>The Granola integration imports your Granola meeting notes into the Extracts module for AI analysis.</p><ol><li>Go to Settings &gt; Integrations.</li><li>Find the Granola integration and select Connect.</li><li>Enter your Granola API key. You can find your API key in your Granola account settings.</li><li>Lodestone verifies the connection and saves it automatically.</li></ol><h3 id="configuring-granola-auto-sync" tabindex="-1">Configuring Granola auto-sync <a class="header-anchor" href="#configuring-granola-auto-sync" aria-label="Permalink to &quot;Configuring Granola auto-sync&quot;">​</a></h3><p>After connecting:</p><ol><li>In the Granola integration settings, enable <strong>Automatic Sync</strong>.</li><li>Choose a <strong>Sync Interval</strong>: every 12 hours, 24 hours, or weekly.</li><li>Set a <strong>Lookback Window</strong> for how far back to look on each sync cycle.</li><li>Save.</li></ol><hr><h2 id="connecting-tl-dv" tabindex="-1">Connecting tl;dv <a class="header-anchor" href="#connecting-tl-dv" aria-label="Permalink to &quot;Connecting tl;dv&quot;">​</a></h2><p>The tl;dv integration imports recorded meeting transcripts from tl;dv into the Extracts module.</p><ol><li>Go to Settings &gt; Integrations.</li><li>Find the tl;dv integration and select Connect. (tl;dv may also appear in the Add Integration modal — look for it there if it&#39;s not visible in your main integrations list.)</li><li>Enter your tl;dv API key.</li><li>Lodestone verifies the connection and saves it automatically.</li></ol><h3 id="configuring-tl-dv-auto-sync" tabindex="-1">Configuring tl;dv auto-sync <a class="header-anchor" href="#configuring-tl-dv-auto-sync" aria-label="Permalink to &quot;Configuring tl;dv auto-sync&quot;">​</a></h3><p>After connecting:</p><ol><li>In the tl;dv integration settings, enable <strong>Automatic Sync</strong>.</li><li>Choose a <strong>Sync Interval</strong>: every 12 hours, 24 hours, or weekly.</li><li>Set a <strong>Lookback Window</strong> for how far back to look on each sync cycle.</li><li>Save.</li></ol><hr><h2 id="connecting-gong" tabindex="-1">Connecting Gong <a class="header-anchor" href="#connecting-gong" aria-label="Permalink to &quot;Connecting Gong&quot;">​</a></h2><p>The Gong integration works similarly to Fireflies — it brings call transcripts into the Extracts module for AI analysis.</p><ol><li>Go to Settings &gt; Integrations.</li><li>Find the Gong integration and select Connect.</li><li>Authenticate with your Gong account.</li><li>During setup, you&#39;ll be prompted to select which Gong accounts to pull transcripts from. Select the front-line customer-facing colleagues whose calls you want to analyze — typically AEs, CSMs, and SDRs.</li><li>Once connected, the Gong import option becomes available in the Extracts module.</li></ol><blockquote><p><strong>Tip:</strong> Be deliberate about which accounts you select during setup. Selecting too broadly brings in calls with low product signal. Focusing on customer-facing roles produces the most actionable Extracts.</p></blockquote><p>To change which accounts are included after initial setup, return to Settings &gt; Integrations and update the Gong configuration.</p><h3 id="configuring-gong-auto-sync" tabindex="-1">Configuring Gong auto-sync <a class="header-anchor" href="#configuring-gong-auto-sync" aria-label="Permalink to &quot;Configuring Gong auto-sync&quot;">​</a></h3><p>After connecting, you can configure Lodestone to pull new Gong transcripts automatically:</p><ol><li>In the Gong integration settings, enable <strong>Automatic Sync</strong>.</li><li>Choose a <strong>Sync Interval</strong>: every 12 hours, 24 hours, or weekly.</li><li>Set a <strong>Lookback Window</strong> — how many days back Lodestone should look for new calls on each sync cycle (1–90 days).</li><li>Save. Lodestone will now pull new Gong transcripts on your chosen schedule and queue them for analysis in Extracts automatically.</li></ol><hr><h2 id="connecting-jira" tabindex="-1">Connecting JIRA <a class="header-anchor" href="#connecting-jira" aria-label="Permalink to &quot;Connecting JIRA&quot;">​</a></h2><p>The JIRA integration keeps Features and delivery status in sync between Lodestone and JIRA Cloud. It operates at the Feature level — Lodestone Features map to JIRA issues at a level you define (Epic, Story, Task, or Subtask).</p><h3 id="step-1-activate-the-integration" tabindex="-1">Step 1: Activate the integration <a class="header-anchor" href="#step-1-activate-the-integration" aria-label="Permalink to &quot;Step 1: Activate the integration&quot;">​</a></h3><ol><li>Go to Settings &gt; Integrations.</li><li>Find the JIRA integration and select Connect.</li><li>Paste your JIRA API key to authenticate.</li><li>Select which JIRA object level Lodestone Features should map to (Epic, Story, Task, or Subtask).</li></ol><blockquote><p><strong>Note:</strong> The JIRA integration supports JIRA Cloud only. JIRA Server is not currently supported.</p></blockquote><h3 id="step-2-configure-sync-behavior" tabindex="-1">Step 2: Configure sync behavior <a class="header-anchor" href="#step-2-configure-sync-behavior" aria-label="Permalink to &quot;Step 2: Configure sync behavior&quot;">​</a></h3><p>After activating, configure how data flows between systems using three controls:</p><p><strong>Automatic Sync</strong> Enables interval-based polling. Lodestone checks JIRA for updates at a frequency you define (e.g. every hour). Recommended as a baseline for all teams.</p><p><strong>Webhooks</strong> Enables real-time bidirectional updates. Changes in Lodestone immediately update JIRA, and changes in JIRA immediately update Lodestone — no polling delay. Recommended for teams that need immediate status accuracy.</p><p><strong>Status Mapping</strong> Defines how JIRA issue statuses correspond to Lodestone Feature status stages. Because JIRA and Lodestone may use different terminology, you must map them manually. Example:</p><table tabindex="0"><thead><tr><th>JIRA status</th><th>Lodestone status stage</th></tr></thead><tbody><tr><td>To Do, Backlog</td><td>Not Started</td></tr><tr><td>In Progress, In Review</td><td>In Progress</td></tr><tr><td>Done, Closed</td><td>Completed</td></tr></tbody></table><p>Status mappings can be edited at any time. Getting this right is critical — incorrect mapping means Release boards and Roadmaps will reflect inaccurate delivery progress.</p><h3 id="step-3-connect-multiple-jira-projects-if-needed" tabindex="-1">Step 3: Connect multiple JIRA projects (if needed) <a class="header-anchor" href="#step-3-connect-multiple-jira-projects-if-needed" aria-label="Permalink to &quot;Step 3: Connect multiple JIRA projects (if needed)&quot;">​</a></h3><p>A single workspace can connect to multiple JIRA projects. Repeat the connection process for each project, configuring sync behavior and status mapping per project as needed.</p><hr><h2 id="manually-linking-a-feature-to-an-existing-jira-issue" tabindex="-1">Manually Linking a Feature to an Existing JIRA Issue <a class="header-anchor" href="#manually-linking-a-feature-to-an-existing-jira-issue" aria-label="Permalink to &quot;Manually Linking a Feature to an Existing JIRA Issue&quot;">​</a></h2><p>If you have existing JIRA issues that predate the integration, you can manually link them to Lodestone Features rather than creating new ones.</p><ol><li>Open the Feature Detail page for the Feature you want to link.</li><li>Find the JIRA link option.</li><li>Enter or search for the JIRA issue to link.</li><li>Once linked, the Feature and JIRA issue sync according to your configured sync behavior.</li></ol><hr><h2 id="unlinking-a-feature-from-a-jira-issue" tabindex="-1">Unlinking a Feature from a JIRA Issue <a class="header-anchor" href="#unlinking-a-feature-from-a-jira-issue" aria-label="Permalink to &quot;Unlinking a Feature from a JIRA Issue&quot;">​</a></h2><p>If you need to break the connection between a Feature and a JIRA issue:</p><ol><li>Open the Feature Detail page.</li><li>Find the linked JIRA issue.</li><li>Select the unlink option.</li></ol><p>Unlinking stops future sync between the two objects but does not delete either. The Feature remains in Lodestone; the JIRA issue remains in JIRA.</p><hr><h2 id="triggering-a-manual-sync" tabindex="-1">Triggering a Manual Sync <a class="header-anchor" href="#triggering-a-manual-sync" aria-label="Permalink to &quot;Triggering a Manual Sync&quot;">​</a></h2><p>If automatic sync or webhooks aren&#39;t configured, or you want to force an immediate update:</p><ol><li>Go to Settings &gt; Integrations.</li><li>Find the JIRA integration.</li><li>Trigger a manual sync.</li></ol><hr><h2 id="connecting-asana" tabindex="-1">Connecting Asana <a class="header-anchor" href="#connecting-asana" aria-label="Permalink to &quot;Connecting Asana&quot;">​</a></h2><p>The Asana integration lets you push Backlog items to Asana as tasks and keeps status updates flowing back into Lodestone automatically.</p><h3 id="step-1-generate-a-personal-access-token-in-asana" tabindex="-1">Step 1: Generate a Personal Access Token in Asana <a class="header-anchor" href="#step-1-generate-a-personal-access-token-in-asana" aria-label="Permalink to &quot;Step 1: Generate a Personal Access Token in Asana&quot;">​</a></h3><ol><li>Sign in to your Asana account.</li><li>Go to your Asana profile settings and navigate to the <strong>Apps</strong> or <strong>Developer</strong> section.</li><li>Create a new <strong>Personal Access Token</strong>. Give it a name like &quot;Lodestone Integration&quot;.</li><li>Copy the token — you&#39;ll need it in the next step.</li></ol><h3 id="step-2-connect-the-integration" tabindex="-1">Step 2: Connect the integration <a class="header-anchor" href="#step-2-connect-the-integration" aria-label="Permalink to &quot;Step 2: Connect the integration&quot;">​</a></h3><ol><li>Go to Settings &gt; Integrations in Lodestone.</li><li>Find the Asana integration and select Connect.</li><li>Paste your Personal Access Token.</li><li>Lodestone validates the token and fetches your accessible Asana projects.</li><li>Select the Asana project you want to sync Backlog items to.</li><li>Save. The integration is now active.</li></ol><h3 id="step-3-push-a-backlog-item-to-asana" tabindex="-1">Step 3: Push a Backlog item to Asana <a class="header-anchor" href="#step-3-push-a-backlog-item-to-asana" aria-label="Permalink to &quot;Step 3: Push a Backlog item to Asana&quot;">​</a></h3><p>Once connected, a <strong>Push to Asana</strong> button appears on each Backlog item detail page.</p><ol><li>Open any Backlog item by clicking its name.</li><li>Click <strong>Push to Asana</strong>.</li><li>Lodestone creates a new task in your connected Asana project.</li></ol><p>If the item has already been pushed, the button shows the linked Asana task ID instead of creating a new one.</p><blockquote><p><strong>Note:</strong> Pushing to Asana creates a task from the Backlog item&#39;s name and description. Subsequent status updates from Asana sync back to Lodestone automatically — you do not need to push again after the initial sync.</p></blockquote><hr><h2 id="disconnecting-an-integration" tabindex="-1">Disconnecting an Integration <a class="header-anchor" href="#disconnecting-an-integration" aria-label="Permalink to &quot;Disconnecting an Integration&quot;">​</a></h2><p>To disconnect any integration:</p><ol><li>Go to Settings &gt; Integrations.</li><li>Find the integration and select Disconnect.</li></ol><p>Disconnecting stops all future syncing but preserves existing data in Lodestone. Features, status updates, and any other data already in Lodestone are not removed.</p><hr><p><em>Next: Advanced Features &amp; Customization — sync strategy, status mapping best practices, and managing multiple projects.</em></p>',88)])])}const p=t(i,[["render",s]]);export{d as __pageData,p as default};
